{
"title": "API Health Overview",
"timeRange": { "from": "now-1h", "to": "now" },
"refreshIntervalMs": 15000,
"panels": [
{
"title": "Request rate",
"viz": "line",
"description": "Computes the overall request rate in requests per second by counting http_requests within each 1-minute bucket across all services, to track API traffic over the dashboard window.",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, count(*) / 60.0 AS req_per_sec FROM http_requests GROUP BY minute ORDER BY minute ASC",
"timeField": "minute"
},
"options": {
"unit": "req/s",
"decimals": 1,
"legend": "none"
},
"layout": { "x": 0, "y": 0, "w": 6, "h": 4 }
,
"format": "number"
,
"refreshIntervalMs": 15000
,
"timeRange": { "from": "now-1h", "to": "now" }
,
"id": "api-request-rate"
},
{
"title": "p95 latency",
"viz": "line",
"description": "Computes the 95th percentile of duration_ms for http_requests within each 1-minute bucket across all services, in milliseconds, to track p95 latency over the dashboard window.",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, percentile_cont(0.95) WITHIN GROUP (ORDER BY duration_ms) AS p95_latency_ms FROM http_requests GROUP BY minute ORDER BY minute ASC",
"timeField": "minute"
},
"format": "ms",
"options": {
"decimals": 0,
"legend": "none"
},
"layout": { "x": 6, "y": 0, "w": 6, "h": 4 }
,
"refreshIntervalMs": 15000
,
"timeRange": { "from": "now-1h", "to": "now" }
,
"id": "api-p95-latency"
},
{
"title": "Current 5xx error rate",
"viz": "stat",
"description": "Computes the percentage of http_requests with status between 500 and 599 relative to all requests within each 1-minute bucket, with the most recent bucket shown as the current 5xx error rate and its recent history drawn behind it.",
"query": {
"sourceId": "eval-demo",
"sql": "SELECT time_bucket('1 minute', ts) AS minute, round(100.0 * count(*) FILTER (WHERE status >= 500 AND status < 600) / count(*), 2) AS error_rate_pct FROM http_requests GROUP BY minute ORDER BY minute ASC",
"timeField": "minute"
},
"format": "percent",
"options": {
"value": "error_rate_pct",
"decimals": 2,
"sparkline": true,
"thresholds": [
{ "value": 1, "color": "warning" },
{ "value": 5, "color": "danger" }
]
},
"layout": { "x": 0, "y": 4, "w": 6, "h": 4 }
,
"refreshIntervalMs": 15000
,
"timeRange": { "from": "now-1h", "to": "now" }
,
"id": "api-5xx-error-rate"
}
]
}
